window.CONTENT_PARTS = window.CONTENT_PARTS || [];
window.CONTENT_PARTS.push({ lang: "en", units: [
{ id: "en-feelings", group: "Word banks", order: 30, title: "Feelings word bank",
  intro: "Feelings are the heart of every good story. Pick a feeling to see stronger words for it, body language that shows it, and similes that paint it.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Each feeling has a <b>ladder</b> of words from mild to very strong. Choose the step that matches how big the feeling really is. Being a little nervous before a spelling test is not the same as being panicky when you are lost!" },
    { type: "wordbank", title: "Feelings to explore", items: [
      { name: "Happy", hue: 50, ladder: ["content", "cheerful", "delighted", "overjoyed", "ecstatic"],
        show: ["A huge grin spread across my face.", "I skipped all the way home, humming a tune.", "I could not stop giggling.", "I punched the air and cheered.", "My eyes crinkled at the corners as I smiled."],
        similes: ["as happy as a puppy with a new toy", "my heart felt as light as a feather", "I felt like I was floating on a cloud"],
        tell: "I was very happy.", showEx: "I punched the air and let out a loud whoop, grinning from ear to ear." },
      { name: "Excited", hue: 25, ladder: ["keen", "eager", "excited", "thrilled", "bursting with excitement"],
        show: ["I bounced on my toes.", "I could hardly sit still in my seat.", "My eyes sparkled.", "I counted down the days on the calendar.", "I talked so fast that my words tumbled over each other."],
        similes: ["like a bottle of fizzy drink about to pop", "like a child on the first day of the school holidays", "my heart raced like a car on a racetrack"],
        tell: "I was excited about the trip.", showEx: "I bounced on my toes at the school gate, checking my watch every ten seconds as I waited for the bus." },
      { name: "Proud", hue: 160, ladder: ["satisfied", "pleased", "proud", "triumphant", "on top of the world"],
        show: ["I held my head high.", "I puffed out my chest.", "I beamed from ear to ear.", "I could not wait to show Mum.", "I walked to the stage with my back as straight as a ruler."],
        similes: ["I felt as tall as a giant", "as proud as a peacock", "I glowed like a lantern"],
        tell: "I was proud of my test result.", showEx: "I held the paper up high and beamed. All the way home, I kept peeking at the big red tick at the top." },
      { name: "Grateful", hue: 130, ladder: ["thankful", "grateful", "touched", "deeply moved", "moved to tears"],
        show: ["A warm feeling filled my chest.", "My eyes welled up with happy tears.", "I hugged her tightly.", "I said thank you three times.", "I clutched the gift close to my heart."],
        similes: ["warm like a cup of hot Milo on a rainy day", "her kindness wrapped around me like a soft blanket"],
        tell: "I was grateful to my friend.", showEx: "A warm feeling filled my chest. I hugged Mei Ling tightly and whispered, “I’ll never forget this.”" },
      { name: "Relieved", hue: 185, ladder: ["comforted", "reassured", "relieved", "hugely relieved", "flooded with relief"],
        show: ["I let out a long sigh.", "My shoulders relaxed.", "I could finally breathe again.", "My legs went weak with relief.", "I sank into the chair and closed my eyes."],
        similes: ["as if a heavy bag had been lifted off my shoulders", "like a balloon gently letting out its air"],
        tell: "I was relieved when I found my bag.", showEx: "I let out a long sigh and hugged the bag to my chest. I could finally breathe again." },
      { name: "Surprised", hue: 290, ladder: ["startled", "surprised", "amazed", "astonished", "stunned"],
        show: ["My jaw dropped.", "I gasped.", "I blinked twice, not believing my eyes.", "I nearly dropped my cup.", "My eyebrows shot up."],
        similes: ["my eyes grew as wide as saucers", "I stood as still as a statue"],
        tell: "I was surprised to see the cake.", showEx: "My jaw dropped. I blinked twice, not believing my eyes, as the candles flickered in the dark." },
      { name: "Shocked", hue: 310, ladder: ["taken aback", "shaken", "shocked", "horrified", "frozen in shock"],
        show: ["The colour drained from my face.", "My mouth opened, but no words came out.", "I stood rooted to the spot.", "The pencil slipped from my fingers.", "My hand flew to my mouth."],
        similes: ["the news hit me like a bucket of ice water", "as if the floor had vanished beneath my feet"],
        tell: "I was shocked when I saw the broken window.", showEx: "The colour drained from my face. I stood rooted to the spot, staring at the jagged hole in the glass." },
      { name: "Confused", hue: 250, ladder: ["unsure", "puzzled", "confused", "baffled", "bewildered"],
        show: ["I scratched my head.", "I frowned at the question.", "My mind went blank.", "I tilted my head to one side.", "I read the sentence again, then again."],
        similes: ["my thoughts were as tangled as a ball of string", "like trying to find my way in a thick fog"],
        tell: "I was confused by the question.", showEx: "I frowned at the question and scratched my head. I read it three times, but my mind stayed completely blank." },
      { name: "Curious", hue: 70, ladder: ["interested", "curious", "intrigued", "fascinated", "burning with curiosity"],
        show: ["I leaned closer to get a better look.", "I tiptoed over to peek inside.", "Question after question popped into my head.", "I pressed my ear against the door.", "I could not take my eyes off the box."],
        similes: ["as curious as a kitten", "my curiosity tugged at me like a kite string"],
        tell: "I was curious about the box.", showEx: "I tiptoed over and leaned closer. What could be rattling inside that dusty old box?" },
      { name: "Determined", hue: 15, ladder: ["willing", "keen to try", "determined", "resolute", "nothing could stop me"],
        show: ["I gritted my teeth and kept going.", "I tightened my grip on the racket.", "I wiped the sweat from my forehead and tried again.", "I set my jaw and stared at the finishing line.", "I refused to give up."],
        similes: ["as steady as a rock", "like a bulldozer pushing forward"],
        tell: "I was determined to win the race.", showEx: "I gritted my teeth and fixed my eyes on the finishing line. My legs ached, but I pushed harder." },
      { name: "Hopeful", hue: 100, ladder: ["wishful", "hopeful", "optimistic", "confident", "certain"],
        show: ["I crossed my fingers behind my back.", "I held my breath as she opened the envelope.", "A small smile tugged at my lips.", "I looked up at the sky and made a silent wish.", "I checked the letterbox every morning."],
        similes: ["hope flickered in me like a tiny candle", "like the first ray of sunshine after rain"],
        tell: "I was hopeful that I would be chosen.", showEx: "I crossed my fingers behind my back as Mr Lim read out the names. A small smile tugged at my lips." },
      { name: "Calm", hue: 175, ladder: ["settled", "calm", "peaceful", "serene", "completely at ease"],
        show: ["I took a slow, deep breath.", "My hands rested still on my lap.", "I listened to the gentle hum of the fan.", "I closed my eyes and let my shoulders drop.", "I spoke in a soft, steady voice."],
        similes: ["as calm as a still pond", "as peaceful as a sleeping baby"],
        tell: "I felt calm before my performance.", showEx: "I took a slow, deep breath and let my shoulders drop. My fingers rested lightly on the piano keys." },
      { name: "Worried", hue: 265, ladder: ["concerned", "uneasy", "worried", "troubled", "worried sick"],
        show: ["I chewed on my fingernails.", "I paced up and down the corridor.", "I kept glancing at the clock.", "A frown creased my forehead.", "I tossed and turned all night."],
        similes: ["worry gnawed at me like a mouse at a biscuit", "my stomach twisted like a wet towel"],
        tell: "I was worried about my sick grandmother.", showEx: "I paced up and down the hospital corridor, glancing at the clock every few minutes. Why was the doctor taking so long?" },
      { name: "Nervous", hue: 275, ladder: ["uneasy", "jittery", "nervous", "anxious", "panicky"],
        show: ["Butterflies fluttered in my stomach.", "My palms were sweaty.", "I bit my lip.", "My voice came out as a squeak.", "I kept tapping my foot."],
        similes: ["my knees knocked together like castanets", "as jumpy as a cat in a thunderstorm"],
        tell: "I was nervous before the spelling test.", showEx: "Butterflies fluttered in my stomach. I wiped my sweaty palms on my shorts again and again." },
      { name: "Scared", hue: 230, ladder: ["wary", "scared", "frightened", "terrified", "petrified"],
        show: ["My heart pounded against my chest.", "My legs turned to jelly.", "A chill ran down my spine.", "I froze on the spot.", "I squeezed my eyes shut."],
        similes: ["as pale as a ghost", "trembling like a leaf in the wind", "my heart thumped like a drum"],
        tell: "I was very scared.", showEx: "My legs turned to jelly and a chill ran down my spine. I could not move." },
      { name: "Sad", hue: 210, ladder: ["down", "unhappy", "sad", "heartbroken", "devastated"],
        show: ["My eyes stung with tears.", "A lump formed in my throat.", "My shoulders slumped.", "I dragged my feet all the way home.", "I pushed my food around my plate."],
        similes: ["my heart felt as heavy as a stone", "like a flower drooping in the rain"],
        tell: "The boy was sad when his team lost.", showEx: "Jun Hao’s shoulders slumped. He stared at the ground as a tear rolled down his cheek." },
      { name: "Lonely", hue: 200, ladder: ["left out", "lonely", "isolated", "forgotten", "abandoned"],
        show: ["I sat alone at the end of the bench.", "The laughter of the others felt far away.", "I pretended to read my book.", "Nobody looked my way.", "I ate my sandwich in silence."],
        similes: ["like a single shoe without its pair", "like a lone star in an empty sky"],
        tell: "I felt lonely at recess.", showEx: "I sat alone at the end of the bench, pretending to read, while laughter floated over from the other table." },
      { name: "Disappointed", hue: 220, ladder: ["let down", "disappointed", "discouraged", "dejected", "crushed"],
        show: ["My smile faded.", "My heart sank.", "I let out a heavy sigh.", "I blinked back tears.", "I slid the paper quickly into my bag."],
        similes: ["like a balloon slowly losing its air", "my hopes popped like a soap bubble"],
        tell: "I was disappointed with my marks.", showEx: "My heart sank when I saw the red marks. I let out a heavy sigh and slid the paper into my bag." },
      { name: "Frustrated", hue: 5, ladder: ["bothered", "annoyed", "frustrated", "exasperated", "at my wits’ end"],
        show: ["I threw my pencil down on the desk.", "I groaned and buried my face in my hands.", "I tugged at my hair.", "I let out a loud huff.", "I rubbed out the answer so hard that the paper tore."],
        similes: ["like a fly buzzing against a closed window", "like a kettle about to whistle"],
        tell: "I was frustrated with my maths homework.", showEx: "I rubbed out my answer so hard that the paper tore. With a loud groan, I buried my face in my hands." },
      { name: "Regretful", hue: 40, ladder: ["sorry", "regretful", "deeply sorry", "remorseful", "consumed by regret"],
        show: ["I wished I could turn back the clock.", "The words I had said kept replaying in my mind.", "I stared at the floor, unable to speak.", "I wrote an apology note three times before I was happy with it.", "My throat tightened every time I saw her."],
        similes: ["my unkind words stuck to me like gum on a shoe", "regret sat on my shoulders like a heavy schoolbag"],
        tell: "I regretted shouting at my brother.", showEx: "My angry words kept replaying in my head. If only I could turn back the clock and take them back." },
      { name: "Guilty", hue: 30, ladder: ["uncomfortable", "sorry", "guilty", "ashamed", "consumed by guilt"],
        show: ["I could not look her in the eye.", "A heavy feeling sat in my stomach.", "I hung my head.", "I lay awake that night thinking about it.", "I fiddled with the hem of my shirt."],
        similes: ["the secret sat in my chest like a stone", "guilt followed me like a shadow"],
        tell: "I felt guilty for lying.", showEx: "I hung my head and could not look Mum in the eye. A heavy feeling sat in my stomach." },
      { name: "Embarrassed", hue: 340, ladder: ["awkward", "sheepish", "embarrassed", "humiliated", "mortified"],
        show: ["My cheeks burned.", "I stared at my shoes.", "I let out a nervous laugh.", "I wished the ground would swallow me up.", "I hid my face behind my file."],
        similes: ["my face turned as red as a tomato", "my ears felt as hot as a stove"],
        tell: "I was embarrassed when I fell.", showEx: "My cheeks burned as everyone turned to stare. I wished the ground would swallow me up." },
      { name: "Jealous", hue: 95, ladder: ["a little envious", "envious", "jealous", "bitter", "green with envy"],
        show: ["I folded my arms and looked away.", "A sour feeling twisted inside me.", "I muttered under my breath.", "I pretended not to care.", "I refused to clap with the others."],
        similes: ["jealousy crept over me like a dark cloud", "it gnawed at me like a hungry rat"],
        tell: "I was jealous of my sister’s new bicycle.", showEx: "I folded my arms and looked away as my sister rang the shiny bell. A sour feeling twisted inside me." },
      { name: "Angry", hue: 355, ladder: ["annoyed", "irritated", "angry", "furious", "livid"],
        show: ["My face turned red.", "I clenched my fists.", "I gritted my teeth.", "I stomped out of the room.", "My nostrils flared."],
        similes: ["like a volcano about to erupt", "as fierce as a storm", "my anger bubbled like boiling soup"],
        tell: "My sister was angry.", showEx: "My sister’s face turned red. She clenched her fists and stomped out of the room, slamming the door." }
    ] },
    { type: "rewrite", title: "Show, don’t tell: your turn", intro: "Each sentence <b>tells</b> a feeling. Rewrite it so the reader can <b>see</b> the feeling through actions, the face, the body or speech. Do not use the feeling word itself!", items: [
      { q: "I was nervous before the spelling test.", a: "Butterflies fluttered in my stomach. I kept tapping my pencil on the desk as Mrs Tan walked in with the test papers.", hint: "Think stomach, hands, pencil." },
      { q: "Grandma was happy to see us.", a: "Grandma’s face lit up. She threw open her arms and hugged us so tightly that I could smell her flowery talcum powder." },
      { q: "The boy was scared of the dark.", a: "Wei Ming pulled the blanket over his head. Every creak and rustle in the dark made him jump.", hint: "What does he do with his blanket?" },
      { q: "I was angry with my brother.", a: "I clenched my fists and glared at my brother. “That was mine!” I snapped." },
      { q: "She was sad when her goldfish died.", a: "Aisha stared at the empty tank. A tear rolled down her cheek and dripped onto her hand." },
      { q: "I was surprised by the party.", a: "As the lights flicked on, everyone yelled, “Surprise!” My jaw dropped and my schoolbag slid off my shoulder." },
      { q: "I was excited about going to the zoo.", a: "I was up before my alarm rang. I bounced around the kitchen, asking Dad every five minutes, “Can we go now?”", hint: "When did you wake up?" },
      { q: "Priya was proud of her drawing.", a: "Priya held up her drawing with both hands and beamed. She pinned it on the fridge and kept walking past to admire it." },
      { q: "I was tired after the race.", a: "I collapsed onto the grass, my chest heaving. My legs felt like they were made of rubber." },
      { q: "Jun Hao was embarrassed when he forgot his lines.", a: "Jun Hao’s cheeks turned bright red. He stared at his shoes as a few giggles rippled through the hall." },
      { q: "I was bored during the long car ride.", a: "I pressed my forehead against the window and counted lamp posts. Forty-one, forty-two… I let out a long, loud yawn." },
      { q: "Mum was worried when I came home late.", a: "Mum was standing at the door, phone in hand. “Where were you?” she cried, pulling me into a tight hug." },
      { q: "I was jealous of Ryan’s new phone.", a: "I folded my arms as everyone crowded around Ryan’s shiny new phone. “It’s not that special,” I muttered." },
      { q: "Mei Ling was confused by the map.", a: "Mei Ling turned the map one way, then the other. She frowned and scratched her head. “Wait, where are we?”" },
      { q: "I was relieved when the test was over.", a: "When the bell rang, I let out a long breath and dropped my pencil. My shoulders finally relaxed." },
      { q: "The old man was lonely.", a: "The old man sat alone at the void deck every evening, watching the children play. Nobody stopped to say hello." },
      { q: "I felt guilty about breaking the vase.", a: "I could not look Mum in the eye at dinner. I pushed my rice around the plate, the broken vase still hidden under my bed." },
      { q: "My friend was disappointed when the trip was cancelled.", a: "Aisha’s smile faded. She slowly unpacked her bag, putting the sunscreen and snacks back on the shelf one by one." },
      { q: "I was determined to finish the puzzle.", a: "I gritted my teeth and picked up another piece. I would not go to bed until the last one clicked into place." },
      { q: "The crowd was excited when the singer came on stage.", a: "The crowd leapt to their feet. They screamed, clapped and waved glow sticks high above their heads." }
    ] }
  ] },
{ id: "en-senses", group: "Word banks", order: 31, title: "The five senses",
  intro: "Good writers help the reader feel as if they are really there. Pick a place to find ready-made phrases for what you can see, hear, smell, touch and taste, plus how the place makes you feel.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Do not stop at what you can <b>see</b>. Most children only write about sight. Adding one sound and one smell makes your setting come alive at once." },
    { type: "settings", title: "Choose a place", items: [
      { name: "Classroom", senses: [
        { label: "See", lines: ["sunlight streamed through the louvred windows", "the whiteboard was covered in Mr Tan’s neat handwriting", "rows of water bottles stood on the desks like soldiers"] },
        { label: "Hear", lines: ["the scratching of pencils on paper", "the steady whirr of the ceiling fan", "whispers and muffled giggles from the back row"] },
        { label: "Smell", lines: ["the sharp smell of whiteboard markers", "the fresh, papery smell of new textbooks", "a faint whiff of curry puffs from someone’s lunch box"] },
        { label: "Touch", lines: ["the cool breeze from the fan on my neck", "the smooth wooden desk under my arms", "the sticky page of a well-used dictionary"] },
        { label: "Feelings", lines: ["my stomach fluttered as the test papers were handed out", "a lazy, sleepy feeling crept over me after recess", "I felt safe and settled among my friends"] } ] },
      { name: "Hawker centre", senses: [
        { label: "See", lines: ["steam rose from bowls of fishball soup", "a long queue snaked from the chicken rice stall", "packets of tissue paper left on tables to reserve seats"] },
        { label: "Hear", lines: ["plates and cutlery clattered", "uncles called out orders above the noise", "the wok sizzled and hissed over the flames"] },
        { label: "Smell", lines: ["the fragrance of fried garlic", "smoky satay on the charcoal grill", "the sweet smell of kaya toast"] },
        { label: "Touch", lines: ["the sticky table under my elbows", "the cold, wet glass of iced lime juice", "the hard plastic stool beneath me"] },
        { label: "Taste", lines: ["the spicy sambal made my tongue tingle", "the char kway teow was smoky and slightly sweet", "the teh tarik was frothy and rich"] } ] },
      { name: "Beach", senses: [
        { label: "See", lines: ["waves crashed onto the shore in white foam", "the sky was painted orange and pink at sunset", "ships dotted the horizon like toy boats"] },
        { label: "Hear", lines: ["seagulls squawked overhead", "the gentle swish of the waves", "children shrieked as the water rushed over their feet"] },
        { label: "Smell", lines: ["the salty sea air", "coconut-scented sunscreen", "smoke from a barbecue pit nearby"] },
        { label: "Touch", lines: ["warm sand squished between my toes", "a cool breeze tugged at my hair", "the rough, ridged shell in my palm"] },
        { label: "Taste", lines: ["salty spray on my lips", "a sweet, melting ice cream potong", "grains of sand in my sandwich"] } ] },
      { name: "Rainy day", senses: [
        { label: "See", lines: ["dark clouds gathered over the HDB blocks", "raindrops raced each other down the window", "a jagged streak of lightning lit up the sky"] },
        { label: "Hear", lines: ["thunder rumbled in the distance", "rain drummed on the roof of the bus shelter", "car tyres swished through the puddles"] },
        { label: "Smell", lines: ["the earthy smell of wet grass", "the damp smell of soaked umbrellas", "the fresh, clean air after the storm"] },
        { label: "Touch", lines: ["my wet shoes squelched with every step", "a chill crept up my arms", "cold drops trickled down the back of my neck"] },
        { label: "Feelings", lines: ["a cosy feeling as I curled up under my blanket", "a gloomy, restless mood settled over me", "I felt trapped indoors"] } ] },
      { name: "Playground", senses: [
        { label: "See", lines: ["children zoomed down the twisty slide", "leaves danced across the rubber mat", "a toddler wobbled towards the see-saw"] },
        { label: "Hear", lines: ["shrieks of laughter", "the creak of the rusty swing", "parents calling their children home for dinner"] },
        { label: "Smell", lines: ["freshly cut grass", "the warm, rubbery smell of the mat in the sun", "a whiff of ice cream from the uncle’s cart"] },
        { label: "Touch", lines: ["the hot metal of the slide on my legs", "the rough rope of the climbing net", "the springy floor under my feet"] },
        { label: "Feelings", lines: ["my heart raced as I swung higher and higher", "I felt free and full of energy", "a burst of courage as I reached the top"] } ] },
      { name: "Night at home", senses: [
        { label: "See", lines: ["shadows stretched across the bedroom wall", "a thin beam of moonlight slipped through the curtains", "the red glow of the air-con light"] },
        { label: "Hear", lines: ["the clock ticked loudly in the silence", "the fridge hummed softly in the kitchen", "a dog barked somewhere far away"] },
        { label: "Smell", lines: ["the faint smell of Mum’s cooking from earlier", "the clean smell of freshly washed sheets", "mosquito coil smoke drifting from the kitchen"] },
        { label: "Touch", lines: ["goosebumps prickled my arms", "the cold floor under my bare feet", "my soft, worn bolster against my cheek"] },
        { label: "Feelings", lines: ["every small sound made me jump", "I felt warm and drowsy", "my imagination ran wild in the dark"] } ] },
      { name: "MRT train", senses: [
        { label: "See", lines: ["passengers stared down at their phones", "the map above the door blinked with tiny lights", "a sea of heads swayed as the train turned"] },
        { label: "Hear", lines: ["the beep-beep-beep of the closing doors", "the calm voice announcing the next station", "the rumble of wheels on the tracks"] },
        { label: "Smell", lines: ["a mix of perfume and sweat during peak hour", "the cold, metallic smell of the air-con", "the buttery smell of bread from someone’s bakery bag"] },
        { label: "Touch", lines: ["the cold metal pole under my hand", "being squashed between two tall adults", "the icy blast of air-con on my arms"] },
        { label: "Feelings", lines: ["a jolt as the train lurched forward", "the gentle rocking that made me sleepy", "a rush of panic when I nearly missed my stop"] } ] },
      { name: "Wet market", senses: [
        { label: "See", lines: ["piles of glistening fish on beds of ice", "bright red chillies heaped in baskets", "aunties haggling with the stallholders"] },
        { label: "Hear", lines: ["the thwack of a cleaver on a chopping board", "stallholders shouting out their prices", "the splash of water hosed across the floor"] },
        { label: "Smell", lines: ["the strong, fishy smell of the seafood stalls", "the sweet scent of ripe mangoes", "the sharp smell of fresh lemongrass"] },
        { label: "Touch", lines: ["the wet, slippery floor under my slippers", "the plastic bag handles cutting into my fingers", "the prickly skin of a durian"] },
        { label: "Taste", lines: ["a free slice of juicy papaya from the fruit seller", "the sweetness of a just-peeled rambutan", "a salty, crunchy ikan bilis snack"] } ] },
      { name: "Hospital", senses: [
        { label: "See", lines: ["long white corridors that all looked the same", "nurses hurrying past in blue uniforms", "rows of anxious faces in the waiting area"] },
        { label: "Hear", lines: ["the steady beep of a heart monitor", "the squeak of trolley wheels", "a voice calling out queue numbers"] },
        { label: "Smell", lines: ["the strong smell of disinfectant", "the clean, sharp smell of hand sanitiser", "a bouquet of lilies by the bed"] },
        { label: "Touch", lines: ["Grandpa’s thin, wrinkled hand in mine", "the stiff, starched hospital blanket", "the cold plastic chair"] },
        { label: "Feelings", lines: ["a knot of worry in my stomach", "time seemed to crawl", "a wave of relief when the doctor smiled"] } ] },
      { name: "School hall on concert day", senses: [
        { label: "See", lines: ["bright spotlights shone on the stage", "parents waved and held up their phones", "the heavy red curtains swayed"] },
        { label: "Hear", lines: ["the buzz of a hundred excited voices", "the screech of the microphone being tested", "thunderous applause after each item"] },
        { label: "Smell", lines: ["the powdery smell of stage make-up", "hairspray hanging in the air backstage", "flowers in a bouquet a parent was holding"] },
        { label: "Touch", lines: ["my scratchy costume", "the cool, smooth body of my violin", "the dusty velvet curtain against my arm"] },
        { label: "Feelings", lines: ["my heart thumping as we waited in the wings", "my hands trembled as I stepped into the light", "a rush of joy when the audience cheered"] } ] }
    ] },
    { type: "chips", title: "Sense words", groups: [
      { title: "Sound words (onomatopoeia)", words: ["crash", "bang", "thud", "creak", "sizzle", "splash", "rustle", "whoosh", "clang", "buzz", "drip", "screech", "pitter-patter", "crackle", "rumble", "hiss", "thump", "slurp", "ding-dong", "squelch", "boom", "tick-tock"], ex: "Drip, drip, drip. The tap in the dark kitchen would not stop.", note: "Start a paragraph with a sound word to grab attention." },
      { title: "Sight words", words: ["glittering", "gloomy", "dazzling", "shadowy", "towering", "tiny", "colourful", "murky", "gleaming", "faded", "flickering", "misty", "spotless", "crumpled"], ex: "A flickering lamp lit the gloomy corridor." },
      { title: "Smell words", words: ["fragrant", "smoky", "musty", "fresh", "sweet", "rotten", "salty", "spicy", "earthy", "sour", "stale", "flowery", "pungent"], ex: "The musty storeroom smelled of old newspapers and dust." },
      { title: "Touch words", words: ["rough", "smooth", "sticky", "icy", "prickly", "slimy", "soft", "scorching", "fluffy", "bumpy", "damp", "silky", "gritty"], ex: "The kitten’s fur was as silky as a scarf against my cheek." },
      { title: "Taste words", words: ["sweet", "sour", "bitter", "salty", "spicy", "juicy", "crunchy", "bland", "tangy", "creamy", "chewy", "zesty", "mouth-watering"], ex: "The tangy assam fish made my lips pucker." }
    ] }
  ] },
{ id: "en-people", group: "Word banks", order: 32, title: "Describing people",
  intro: "Help your reader picture the people in your story. Choose one or two details that matter, then show what the person is like through what they do.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Do not list every detail from head to toe. Pick the one or two details that matter to your story, like a crumpled uniform for a messy boy or trembling hands for a nervous girl." },
    { type: "chips", title: "Appearance", groups: [
      { title: "Face", words: ["round", "thin", "freckled", "wrinkled", "rosy-cheeked", "pale", "a gap-toothed grin", "dimples", "bushy eyebrows", "a crooked smile", "a pointy chin", "sun-tanned"], ex: "Grandma’s wrinkled face broke into a gap-toothed grin." },
      { title: "Hair", words: ["silky", "spiky", "curly", "frizzy", "neatly combed", "tangled", "a messy fringe", "a long plait", "a tight ponytail", "greying", "shoulder-length", "close-cropped"], ex: "Aisha tugged at her long plait whenever she was thinking." },
      { title: "Eyes", words: ["sparkling", "twinkling", "piercing", "teary", "sleepy", "narrowed", "wide and curious", "kind", "bloodshot", "darting"], ex: "The stranger’s darting eyes made me feel uneasy." },
      { title: "Build", words: ["lanky", "stocky", "petite", "plump", "wiry", "broad-shouldered", "skinny", "towering", "frail", "sturdy", "hunched"], ex: "The lanky boy had to duck to get through the doorway." },
      { title: "Clothes", words: ["crisp school uniform", "crumpled shirt", "faded T-shirt", "muddy shoes", "oversized hoodie", "neatly ironed", "a baju kurung", "a cheongsam", "a worn-out cap", "squeaky new shoes"], ex: "Jun Hao’s shirt was crumpled and one shoelace was always untied." },
      { title: "Voice", words: ["booming", "soft", "squeaky", "croaky", "gentle", "shrill", "husky", "trembling", "calm and steady", "sing-song", "gruff"], ex: "“Who’s there?” called a gruff voice from the dark." },
      { title: "Movement", words: ["shuffled", "strode", "waddled", "tiptoed", "limped", "swaggered", "darted", "plodded", "skipped", "hobbled", "glided", "fidgeted"], ex: "The old uncle hobbled to the bus stop, leaning on his walking stick." }
    ] },
    { type: "chips", title: "Personality traits (with proof!)", groups: [
      { title: "Kind and caring", words: ["kind", "generous", "thoughtful", "caring", "helpful", "gentle"], ex: "Mei Ling quietly slid half of her sandwich across to the new girl, who had no lunch.", note: "Show kindness through a small action, not a speech." },
      { title: "Honest and responsible", words: ["honest", "responsible", "reliable", "trustworthy", "hardworking", "punctual"], ex: "Even though no one saw him, Wei Ming walked back to the shop to return the extra two dollars in change." },
      { title: "Brave and bold", words: ["brave", "confident", "daring", "adventurous", "determined", "bold"], ex: "Priya’s knees were shaking, but she raised her hand and volunteered to speak first." },
      { title: "Cheerful and fun", words: ["cheerful", "witty", "playful", "lively", "friendly", "optimistic"], ex: "Even on rainy days, Ahmad whistled all the way to class and greeted the security guard by name." },
      { title: "Quiet and careful", words: ["shy", "timid", "patient", "calm", "careful", "observant"], ex: "Grandpa waited patiently, without a single sigh, as I tied and re-tied my shoelaces." },
      { title: "Difficult traits", words: ["selfish", "bossy", "stubborn", "careless", "mischievous", "impatient", "boastful", "lazy", "rude", "greedy", "sneaky", "grumpy"], ex: "Ryan was mischievous. He once hid all of Dad’s socks inside the rice cooker.", note: "Even a ‘bad’ trait can change by the end of a story." }
    ] },
    { type: "rewrite", title: "Show this trait through an action", intro: "Do not just name the trait. Write one or two sentences where the person <b>does something</b> that proves it.", items: [
      { q: "Show that Aunty Rosie is generous.", a: "Every Friday, Aunty Rosie bought an extra packet of nasi lemak and gave it to the old cleaner at the void deck." },
      { q: "Show that Jun Hao is careless.", a: "Jun Hao flung his bag onto the floor, and his water bottle rolled out and leaked all over his homework. It was the third time this week." },
      { q: "Show that Mei Ling is honest.", a: "When the cashier gave her ten dollars too much, Mei Ling slid the note back across the counter. “I think you gave me too much,” she said." },
      { q: "Show that my brother is lazy.", a: "My brother lay on the sofa with the remote control in one hand and a packet of potato chips in the other. “Can you get me some water?” he groaned, without looking up." },
      { q: "Show that Priya is brave.", a: "While the rest of us stood frozen, Priya stepped forward, picked up the trembling kitten and carried it away from the busy road." },
      { q: "Show that the coach is strict.", a: "Coach Lim blew his whistle sharply. “Late again? Ten laps around the field, now!” Nobody dared to argue." },
      { q: "Show that Grandpa is patient.", a: "Grandpa showed me how to tie the kite string for the fifth time, smiling as if it were the first." },
      { q: "Show that Ahmad is boastful.", a: "Ahmad waved his medal in our faces. “Did I tell you I came first? Out of fifty runners? Without even trying?”" }
    ] }
  ] },
{ id: "en-places", group: "Word banks", order: 33, title: "Weather, time and places",
  intro: "Where and when does your story happen? Use these words to set the scene, and let the weather match the mood of your story.",
  blocks: [
    { type: "chips", title: "Weather words", groups: [
      { title: "Sunny", words: ["bright", "cloudless", "golden sunshine", "a clear blue sky", "sunlight sparkled", "glorious morning"], ex: "Golden sunshine poured over the field as we lined up for Sports Day." },
      { title: "Hot", words: ["scorching", "sweltering", "blazing", "humid", "sticky", "the sun beat down"], ex: "The sun beat down on our backs, and sweat trickled into my eyes." },
      { title: "Rainy", words: ["drizzle", "downpour", "pouring rain", "torrential", "spitting", "puddles", "soaked to the skin"], ex: "A sudden downpour sent everyone scrambling for the shelter of the void deck." },
      { title: "Stormy", words: ["thunder rumbled", "lightning flashed", "howling wind", "angry clouds", "a raging storm", "gloomy"], ex: "Angry clouds rolled in, and thunder rumbled like a giant clearing its throat." },
      { title: "Windy", words: ["breezy", "gusty", "blustery", "the wind whistled", "leaves swirled", "trees swayed"], ex: "A gust of wind snatched the worksheet from my hand and sent it flying." },
      { title: "Cool evening", words: ["a gentle breeze", "mild", "refreshing", "the air cooled", "a soft orange glow", "dusk"], ex: "A gentle breeze drifted through the park as the sky faded to a soft orange glow." }
    ] },
    { type: "chips", title: "Time of day", groups: [
      { title: "Morning", words: ["at the crack of dawn", "at daybreak", "as the sun rose", "bright and early", "before the birds woke up"], ex: "At the crack of dawn, Dad shook me awake for our fishing trip." },
      { title: "Afternoon", words: ["in the blazing afternoon", "after lunch", "during the hottest part of the day", "after school"], ex: "After school, we raced to the playground before the rain came." },
      { title: "Evening", words: ["as dusk fell", "as the sun set", "at twilight", "as the street lamps flickered on"], ex: "As the street lamps flickered on, I realised I had no idea where I was." },
      { title: "Night", words: ["in the dead of night", "at the stroke of midnight", "under a starless sky", "long after everyone was asleep"], ex: "In the dead of night, a strange scratching sound came from the kitchen." }
    ] },
    { type: "chips", title: "Place words", groups: [
      { title: "Busy places", words: ["bustling", "crowded", "packed", "noisy", "lively", "chaotic", "teeming with people"], ex: "The bustling night market was teeming with people." },
      { title: "Quiet places", words: ["deserted", "silent", "still", "peaceful", "empty", "abandoned", "eerie"], ex: "The deserted corridor was so silent that I could hear my own footsteps." },
      { title: "Beautiful places", words: ["breathtaking", "picturesque", "lush", "sparkling", "colourful", "magnificent"], ex: "We stood at the top of the hill and gazed at the breathtaking view." },
      { title: "Messy or old places", words: ["cluttered", "dusty", "run-down", "shabby", "cramped", "cobwebbed", "crumbling"], ex: "The cluttered storeroom was full of dusty boxes and cobwebbed chairs." }
    ] },
    { type: "tip", html: "<b>Tip:</b> Weather can mirror feelings. Grey skies and rain can match a sad or worried moment. Bright sunshine after a storm can match relief or a happy ending." },
    { type: "cards", title: "Weather that matches the mood", items: [
      { tag: "Worried", title: "Gathering clouds", text: "The sky darkens as trouble builds.", ex: "Dark clouds gathered over the school, just like the worry gathering in my chest." },
      { tag: "Sad", title: "Steady rain", text: "Rain can echo tears.", ex: "Rain streamed down the window as I waited for a phone call that never came." },
      { tag: "Scared", title: "A wild storm", text: "Thunder and wind make a tense scene even tenser.", ex: "Thunder cracked overhead, and the lights flickered. Then everything went black." },
      { tag: "Relieved", title: "Sun after rain", text: "Clearing skies show that the problem is over.", ex: "As we stepped out of the clinic, the rain stopped and a pale rainbow appeared over the blocks." },
      { tag: "Happy", title: "A bright morning", text: "Sunshine fits a joyful start or ending.", ex: "Sunlight danced on the water as we set off in our kayak, laughing and splashing." },
      { tag: "Lonely", title: "A grey, still evening", text: "Quiet, grey weather can make loneliness feel bigger.", ex: "The evening was grey and still. Not even a bird sang as I walked home alone." }
    ] }
  ] },
{ id: "en-wordswap", group: "Word banks", order: 34, title: "Word swap",
  intro: "Some words are used so often that they become dull. Swap them for stronger words that tell the reader exactly what happened.",
  blocks: [
    { type: "table", title: "Overused words and better choices", head: ["Instead of", "Try"], weakCol: 0, rows: [
      ["said", "whispered, shouted, muttered, exclaimed, stammered, sobbed, giggled, snapped, pleaded, replied"],
      ["walked", "strolled, trudged, tiptoed, marched, wandered, staggered, shuffled, strode"],
      ["ran", "sprinted, raced, dashed, bolted, scurried, zoomed, charged"],
      ["looked", "glanced, stared, peered, gazed, glared, squinted, peeked"],
      ["ate", "gobbled, munched, nibbled, devoured, slurped, wolfed down"],
      ["went", "headed, rushed, made my way, set off, hurried, returned"],
      ["got", "received, collected, earned, grabbed, fetched, caught"],
      ["took", "grabbed, snatched, seized, picked up, carried, borrowed"],
      ["put", "placed, dropped, slid, tucked, flung, laid"],
      ["cried", "sobbed, wept, wailed, sniffled, howled, whimpered"],
      ["laughed", "giggled, chuckled, chortled, cackled, roared, sniggered"],
      ["fell", "tumbled, toppled, slipped, stumbled, plunged, collapsed"],
      ["nice", "kind, friendly, pleasant, lovely, thoughtful, delightful"],
      ["good", "excellent, wonderful, fantastic, brilliant, outstanding"],
      ["bad", "terrible, awful, horrible, dreadful, disastrous"],
      ["big", "huge, enormous, gigantic, massive, towering"],
      ["small", "tiny, minute, miniature, pocket-sized, microscopic"],
      ["happy", "cheerful, delighted, overjoyed, thrilled, elated"],
      ["sad", "unhappy, miserable, heartbroken, gloomy, glum"],
      ["scary", "frightening, terrifying, spine-chilling, eerie, creepy"],
      ["a lot of", "plenty of, heaps of, crowds of, countless, dozens of"]
    ] },
    { type: "table", title: "Replace “very ___” with one strong word", head: ["Instead of", "Try"], weakCol: 0, rows: [
      ["very big", "enormous"], ["very small", "tiny"], ["very hot", "scorching"], ["very cold", "freezing"],
      ["very tired", "exhausted"], ["very hungry", "starving"], ["very scared", "terrified"], ["very happy", "overjoyed"],
      ["very angry", "furious"], ["very loud", "deafening"], ["very quiet", "silent"], ["very good", "excellent"],
      ["very bad", "terrible"], ["very pretty", "gorgeous"], ["very fast", "lightning-fast"], ["very slow", "sluggish"],
      ["very clean", "spotless"], ["very dirty", "filthy"], ["very wet", "soaked"], ["very old", "ancient"],
      ["very sad", "heartbroken"], ["very surprised", "astonished"], ["very funny", "hilarious"], ["very smart", "brilliant"],
      ["very bright", "dazzling"], ["very easy", "effortless"]
    ] },
    { type: "tip", html: "<b>Tip:</b> If you find yourself writing <b>very</b>, stop and ask: is there one word that says it better? “I was starving” is stronger than “I was very hungry”." },
    { type: "chips", title: "Connectors to link your ideas", groups: [
      { title: "Time", words: ["First", "Soon after", "Moments later", "Meanwhile", "That evening", "The next morning", "After a while", "Before long", "Finally", "At last"], ex: "Before long, the whole class had gathered round." },
      { title: "Instead of “Suddenly”", words: ["Without warning", "All of a sudden", "In a flash", "Out of nowhere", "Just then", "In the blink of an eye", "Before I knew it", "To my horror"], ex: "Without warning, the lights went out.", note: "Use one of these only at a real turning point." },
      { title: "Cause and effect", words: ["Because of this", "As a result", "Therefore", "That is why", "Since", "So", "Thanks to"], ex: "I forgot my umbrella. As a result, I arrived at school soaked to the skin." },
      { title: "Contrast", words: ["However", "Although", "Even though", "Despite this", "On the other hand", "Yet", "Instead"], ex: "Although my legs ached, I kept running." },
      { title: "Adding", words: ["Also", "Besides", "Furthermore", "In addition", "What is more", "Not only that,"], ex: "Not only that, the bus was late too." },
      { title: "Concluding", words: ["In the end", "Eventually", "Looking back", "From that day on", "Since then", "All in all"], ex: "Since then, I have always kept my bag zipped and in front of me on the MRT." }
    ] }
  ] },
{ id: "en-idioms", group: "Word banks", order: 35, title: "Idioms and proverbs",
  intro: "Idioms are colourful phrases that mean something different from their words. Proverbs are wise sayings. One or two in a composition make it sparkle.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Use idioms sparingly. One well-placed idiom is better than five squeezed into one paragraph. Make sure the meaning really fits your sentence." },
    { type: "idioms", title: "40 idioms and 15 proverbs", items: [
      { w: "over the moon", py: "", m: "extremely happy", ex: "Priya was over the moon when she was picked for the school choir.", cat: "Feelings" },
      { w: "on cloud nine", py: "", m: "very happy and excited", ex: "After scoring the winning goal, Jun Hao was on cloud nine for the whole week.", cat: "Feelings" },
      { w: "heart in my mouth", py: "", m: "very nervous or frightened", ex: "With my heart in my mouth, I walked onto the stage.", cat: "Feelings" },
      { w: "get cold feet", py: "", m: "to suddenly feel too nervous to do something", ex: "Ahmad got cold feet just before the diving competition.", cat: "Feelings" },
      { w: "down in the dumps", py: "", m: "feeling sad", ex: "Mei Ling was down in the dumps after her best friend moved away.", cat: "Feelings" },
      { w: "jump out of my skin", py: "", m: "to be very startled", ex: "When the door slammed, I nearly jumped out of my skin.", cat: "Feelings" },
      { w: "butterflies in my stomach", py: "", m: "a nervous, fluttery feeling", ex: "I had butterflies in my stomach as I waited for my turn.", cat: "Feelings" },
      { w: "see red", py: "", m: "to become very angry", ex: "When my brother tore my drawing, I saw red.", cat: "Feelings" },
      { w: "tickled pink", py: "", m: "very pleased", ex: "Grandma was tickled pink by our home-made card.", cat: "Feelings" },
      { w: "in the nick of time", py: "", m: "just in time", ex: "The ambulance arrived in the nick of time.", cat: "Time" },
      { w: "once in a blue moon", py: "", m: "very rarely", ex: "Dad cooks dinner once in a blue moon, so we always cheer when he does.", cat: "Time" },
      { w: "in the blink of an eye", py: "", m: "extremely quickly", ex: "In the blink of an eye, the thief had vanished into the crowd.", cat: "Time" },
      { w: "at the eleventh hour", py: "", m: "at the very last moment", ex: "Wei Ming finished his project at the eleventh hour.", cat: "Time" },
      { w: "around the clock", py: "", m: "all day and all night", ex: "The nurses cared for Grandpa around the clock.", cat: "Time" },
      { w: "time flies", py: "", m: "time passes quickly", ex: "Time flies when you are having fun at the beach.", cat: "Time" },
      { w: "call it a day", py: "", m: "to stop working for now", ex: "After three hours of practice, Coach told us to call it a day.", cat: "Time" },
      { w: "a dark horse", py: "", m: "someone who surprises everyone with hidden talent", ex: "Quiet Aisha turned out to be a dark horse in the spelling bee.", cat: "People" },
      { w: "the apple of my eye", py: "", m: "someone you love very much", ex: "My baby sister is the apple of Grandma’s eye.", cat: "People" },
      { w: "a couch potato", py: "", m: "someone who watches a lot of TV and is not active", ex: "During the holidays, my cousin became a couch potato.", cat: "People" },
      { w: "a wet blanket", py: "", m: "someone who spoils other people’s fun", ex: "Don’t be a wet blanket. Come and join the game!", cat: "People" },
      { w: "a busybody", py: "", m: "someone who pokes into other people’s business", ex: "The busybody next door always knew everyone’s secrets.", cat: "People" },
      { w: "as cool as a cucumber", py: "", m: "very calm, even under pressure", ex: "While we panicked, Priya stayed as cool as a cucumber.", cat: "People" },
      { w: "two peas in a pod", py: "", m: "two people who are very alike", ex: "The twins were like two peas in a pod.", cat: "People" },
      { w: "a piece of cake", py: "", m: "very easy", ex: "After all that practice, the test was a piece of cake.", cat: "Effort" },
      { w: "go the extra mile", py: "", m: "to do more than is expected", ex: "Our teacher always goes the extra mile to help us.", cat: "Effort" },
      { w: "burn the midnight oil", py: "", m: "to work late into the night", ex: "My sister burnt the midnight oil before her exams.", cat: "Effort" },
      { w: "give it my best shot", py: "", m: "to try as hard as possible", ex: "I may not win, but I will give it my best shot.", cat: "Effort" },
      { w: "lend a hand", py: "", m: "to help", ex: "Jun Hao lent a hand when the old lady dropped her groceries.", cat: "Effort" },
      { w: "pull my socks up", py: "", m: "to try harder and improve", ex: "After failing the quiz, I knew I had to pull my socks up.", cat: "Effort" },
      { w: "learn the ropes", py: "", m: "to learn how to do something new", ex: "It took me a week to learn the ropes in the school library club.", cat: "Effort" },
      { w: "break the ice", py: "", m: "to make people feel relaxed when they first meet", ex: "Our teacher played a game to break the ice on the first day.", cat: "People" },
      { w: "in hot water", py: "", m: "in trouble", ex: "Ryan was in hot water for drawing on the wall.", cat: "Trouble" },
      { w: "let the cat out of the bag", py: "", m: "to reveal a secret by mistake", ex: "My brother let the cat out of the bag about Mum’s surprise party.", cat: "Trouble" },
      { w: "spill the beans", py: "", m: "to tell a secret", ex: "Come on, spill the beans! Who sent you the card?", cat: "Trouble" },
      { w: "the last straw", py: "", m: "the final problem that makes someone lose patience", ex: "When the dog chewed his shoe, that was the last straw for Dad.", cat: "Trouble" },
      { w: "a blessing in disguise", py: "", m: "something that seems bad but turns out to be good", ex: "Missing the bus was a blessing in disguise, because I met an old friend at the stop.", cat: "Trouble" },
      { w: "bite off more than you can chew", py: "", m: "to take on more than you can manage", ex: "By joining four CCAs, Wei Ming bit off more than he could chew.", cat: "Trouble" },
      { w: "cry over spilt milk", py: "", m: "to be upset about something that cannot be changed", ex: "The vase is broken. There is no use crying over spilt milk.", cat: "Trouble" },
      { w: "face the music", py: "", m: "to accept the results of what you did", ex: "I had to face the music and tell Mum the truth.", cat: "Trouble" },
      { w: "in the same boat", py: "", m: "in the same difficult situation", ex: "Don’t worry, we’re all in the same boat. Nobody understood the question.", cat: "Trouble" },
      { w: "Honesty is the best policy.", py: "", m: "Telling the truth is always the right choice.", ex: "When I returned the wallet, I knew that honesty is the best policy.", cat: "Proverbs" },
      { w: "Practice makes perfect.", py: "", m: "Doing something again and again makes you good at it.", ex: "After weeks of drills, my piano piece was smooth. Practice makes perfect!", cat: "Proverbs" },
      { w: "A friend in need is a friend indeed.", py: "", m: "A true friend helps you when you are in trouble.", ex: "When Aisha shared her notes with me, I learnt that a friend in need is a friend indeed.", cat: "Proverbs" },
      { w: "Look before you leap.", py: "", m: "Think carefully before you act.", ex: "Next time, I will look before I leap and read the instructions first.", cat: "Proverbs" },
      { w: "Better late than never.", py: "", m: "It is better to do something late than not at all.", ex: "I finally said sorry to Wei Ming. Better late than never.", cat: "Proverbs" },
      { w: "Don’t judge a book by its cover.", py: "", m: "Do not judge someone only by how they look.", ex: "The grumpy-looking uncle turned out to be the kindest man. Don’t judge a book by its cover.", cat: "Proverbs" },
      { w: "Every cloud has a silver lining.", py: "", m: "Something good can come from a bad situation.", ex: "I broke my leg, but I read twenty books that month. Every cloud has a silver lining.", cat: "Proverbs" },
      { w: "Actions speak louder than words.", py: "", m: "What you do matters more than what you say.", ex: "Ryan said he was sorry, then fixed my bicycle. Actions speak louder than words.", cat: "Proverbs" },
      { w: "Slow and steady wins the race.", py: "", m: "Working carefully and steadily leads to success.", ex: "I studied a little every day. Slow and steady wins the race.", cat: "Proverbs" },
      { w: "Where there’s a will, there’s a way.", py: "", m: "If you really want to do something, you will find a way.", ex: "Without a ladder, we stacked crates to reach the kite. Where there’s a will, there’s a way.", cat: "Proverbs" },
      { w: "Two heads are better than one.", py: "", m: "Two people working together can solve problems better.", ex: "Mei Ling and I solved the riddle together. Two heads are better than one.", cat: "Proverbs" },
      { w: "Don’t count your chickens before they hatch.", py: "", m: "Do not be too sure of success before it happens.", ex: "Ahmad was already celebrating, but I told him not to count his chickens before they hatched.", cat: "Proverbs" },
      { w: "Prevention is better than cure.", py: "", m: "It is better to stop a problem than to fix it later.", ex: "I always wear a helmet when cycling. Prevention is better than cure.", cat: "Proverbs" },
      { w: "Rome was not built in a day.", py: "", m: "Big things take time and patience.", ex: "My swimming will improve. Rome was not built in a day.", cat: "Proverbs" },
      { w: "The early bird catches the worm.", py: "", m: "People who start early get the best chances.", ex: "We reached the book fair at nine and got the last copy. The early bird catches the worm!", cat: "Proverbs" }
    ] }
  ] },
{ id: "en-showtell", group: "Techniques", order: 40, title: "Show, don’t tell",
  intro: "Telling says what a character feels. Showing lets the reader work it out from clues, just like a detective. Showing makes your story feel real.",
  blocks: [
    { type: "text", html: "When you write <b>“I was scared”</b>, you are <b>telling</b>. When you write <b>“My legs turned to jelly and I could not move”</b>, you are <b>showing</b>. The reader feels the fear with you. Here are six tools you can use to show." },
    { type: "cards", title: "Six ways to show", items: [
      { tag: "Tool 1", title: "Actions", text: "What does the character do with their hands, feet or things around them?", ex: "Wei Ming slammed his book shut and shoved it into his bag." },
      { tag: "Tool 2", title: "Face", text: "Eyes, eyebrows, mouth and cheeks give away feelings.", ex: "Her eyebrows knitted together and her lips pressed into a thin line." },
      { tag: "Tool 3", title: "Body", text: "Shoulders, heart, stomach, legs: feelings live in the body.", ex: "My stomach churned and my knees wobbled as I climbed the stairs." },
      { tag: "Tool 4", title: "Speech", text: "How a character speaks shows feelings: short and sharp, soft and shaky, or loud and fast.", ex: "“I… I didn’t mean to,” she stammered, her voice barely a whisper." },
      { tag: "Tool 5", title: "Thoughts", text: "Let the reader hear what is going on inside the character’s head.", ex: "What if Mum finds out? What if she never trusts me again?" },
      { tag: "Tool 6", title: "Senses", text: "Strong feelings change how things look, sound and feel.", ex: "The ticking clock grew louder and louder until it was all I could hear." }
    ] },
    { type: "cards", title: "Before and after", items: [
      { tag: "Tell", title: "I was nervous on stage.", text: "Show it instead:", ex: "My fingers trembled on the microphone. Hundreds of eyes stared up at me, and my mouth went as dry as sandpaper." },
      { tag: "Tell", title: "Dad was angry about the mess.", text: "Show it instead:", ex: "Dad stood in the doorway, arms folded. A vein throbbed on his forehead. “Who did this?” he asked in a low voice." },
      { tag: "Tell", title: "The puppy was happy.", text: "Show it instead:", ex: "The puppy’s tail wagged so hard that its whole body wiggled. It leapt up and licked my chin." },
      { tag: "Tell", title: "It was a hot day.", text: "Show it instead:", ex: "Sweat trickled down my back, and the tarmac shimmered in the heat. Even the pigeons hid in the shade." },
      { tag: "Tell", title: "Aisha was shy.", text: "Show it instead:", ex: "Aisha peeked out from behind her mother and gave a tiny wave, then quickly hid again." }
    ] },
    { type: "avoid", items: ["I was very happy.", "She felt sad.", "He was angry.", "I was scared.", "Everyone was excited."], note: "These sentences name the feeling but do not let the reader feel it. Use one telling word at most, and support it with showing details." },
    { type: "tip", html: "<b>Tip:</b> You do not have to show everything. Show the <b>big</b> feelings at the important moments, like the problem and the climax. Small moments can simply be told." },
    { type: "rewrite", title: "Turn telling into showing", intro: "Rewrite each telling sentence using at least two of the six tools.", items: [
      { q: "The classroom was noisy.", a: "Chairs scraped, someone was drumming on a desk and three groups were talking over one another at the top of their voices. Mrs Lee had to clap four times before anyone noticed her." },
      { q: "The food was delicious.", a: "I closed my eyes as the rich, peppery gravy hit my tongue. Before I knew it, I was scraping the last grains of rice from my plate." },
      { q: "Wei Ming was hungry.", a: "Wei Ming’s stomach let out a loud growl. He kept peeking at the clock, counting the minutes until recess." },
      { q: "The old house was creepy.", a: "The gate groaned as I pushed it. Cobwebs hung from every corner, and the windows stared at me like empty eyes." },
      { q: "I was cold.", a: "I wrapped my arms around myself and rubbed them hard. My teeth chattered, and I could not feel my toes." },
      { q: "Mum was tired after work.", a: "Mum dropped her bag by the door and sank onto the sofa. She kicked off her shoes and closed her eyes with a long sigh." },
      { q: "The baby was cranky.", a: "My baby brother squirmed and kicked, his face scrunched up and red. He flung his milk bottle onto the floor and wailed." },
      { q: "The teacher was strict.", a: "Mr Goh did not need to raise his voice. One look over his glasses, and the whole class fell silent." },
      { q: "I was in a hurry.", a: "I gobbled down my toast, grabbed my bag and dashed out of the door with one shoe still untied." },
      { q: "The park was peaceful.", a: "Only the chirping of birds and the soft rustle of leaves broke the silence. An old couple strolled hand in hand along the path." },
      { q: "Ahmad was brave.", a: "Ahmad took a deep breath, gripped the edge of the diving board and jumped, while the rest of us stayed frozen at the ladder." },
      { q: "My sister was sick.", a: "My sister lay curled up in bed, her face pale and her forehead burning. She pushed away her favourite porridge without a word." },
      { q: "The stranger was suspicious.", a: "The man kept glancing over his shoulder. He pulled his cap low and edged closer to the unattended bags." },
      { q: "I was impatient waiting for my turn.", a: "I shifted from foot to foot and craned my neck to see the front of the queue. “Hurry up,” I muttered under my breath." },
      { q: "The room was messy.", a: "Clothes spilled out of the cupboard, comic books carpeted the floor and a half-eaten sandwich sat on the pillow." }
    ] }
  ] },
{ id: "en-figurative", group: "Techniques", order: 41, title: "Figurative language",
  intro: "Figurative language helps the reader picture things in a fresh, surprising way. Learn eight tools that real authors use.",
  blocks: [
    { type: "cards", title: "Eight tools", items: [
      { tag: "Compare", title: "Simile", text: "Compares two things using <b>like</b> or <b>as</b>.", ex: "Her laugh rang out like a tinkling bell.<br>The floor was as slippery as an ice rink." },
      { tag: "Compare", title: "Metaphor", text: "Says something <b>is</b> something else, without like or as.", ex: "The classroom was a zoo when the teacher left.<br>Grandpa’s garden was his treasure chest." },
      { tag: "Bring to life", title: "Personification", text: "Gives human actions or feelings to things that are not human.", ex: "The wind howled at the window.<br>The old bicycle groaned under my weight." },
      { tag: "Sound", title: "Onomatopoeia", text: "Words that sound like the noise they describe.", ex: "Splash! The ball landed in the drain.<br>The eggs sizzled and popped in the pan." },
      { tag: "Sound", title: "Alliteration", text: "Several nearby words start with the same sound.", ex: "The slippery snake slithered silently.<br>Big brown boxes blocked the back door." },
      { tag: "Exaggerate", title: "Hyperbole", text: "A huge exaggeration used for effect. It is not meant to be taken literally.", ex: "I have told you a million times!<br>My schoolbag weighs a ton." },
      { tag: "Pattern", title: "Rule of three", text: "Three items in a row sound complete and powerful.", ex: "The hall was hot, crowded and noisy.<br>I ran, I tripped and I tumbled into the mud." },
      { tag: "Question", title: "Rhetorical question", text: "A question asked for effect, not for an answer. It pulls the reader in.", ex: "Who could say no to that puppy face?<br>Why did I ever agree to this?" }
    ] },
    { type: "tip", html: "<b>Tip:</b> Fresh is better than familiar. “As white as snow” is fine, but “as white as a new pair of school shoes” is more surprising and fits a Singapore story better." },
    { type: "mcq", title: "Which technique is this?", intro: "Read each sentence and choose the technique it uses.", items: [
      { q: "The thunder grumbled angrily across the sky.", o: ["Simile", "Personification", "Alliteration"], a: 1, e: "Thunder cannot really grumble angrily. It is given a human action." },
      { q: "Mei Ling was as quiet as a mouse.", o: ["Simile", "Metaphor", "Hyperbole"], a: 0, e: "It compares using “as... as”, so it is a simile." },
      { q: "Crash! The tray hit the floor.", o: ["Rhetorical question", "Rule of three", "Onomatopoeia"], a: 2, e: "“Crash” sounds like the noise it describes." },
      { q: "My brother is a walking dictionary.", o: ["Metaphor", "Simile", "Personification"], a: 0, e: "It says he IS a dictionary, without like or as." },
      { q: "I was so hungry I could eat a whole elephant.", o: ["Alliteration", "Hyperbole", "Simile"], a: 1, e: "Nobody can eat an elephant. It is a big exaggeration." },
      { q: "Five funny frogs flipped forward.", o: ["Onomatopoeia", "Rule of three", "Alliteration"], a: 2, e: "Many words start with the same “f” sound." },
      { q: "The beach was sunny, sandy and full of shrieking children.", o: ["Rule of three", "Metaphor", "Hyperbole"], a: 0, e: "Three descriptions are grouped together for a strong rhythm." },
      { q: "How could I have been so foolish?", o: ["Simile", "Rhetorical question", "Personification"], a: 1, e: "The writer does not expect an answer. The question shows their feelings." },
      { q: "The sun smiled down on the picnic.", o: ["Personification", "Onomatopoeia", "Alliteration"], a: 0, e: "The sun cannot smile. It is given a human action." },
      { q: "The queue at the bubble tea shop was a mile long.", o: ["Rule of three", "Simile", "Hyperbole"], a: 2, e: "The queue was not really a mile long. It is an exaggeration." },
      { q: "The rain fell like a curtain of silver beads.", o: ["Metaphor", "Simile", "Rhetorical question"], a: 1, e: "It compares using “like”." },
      { q: "Bzzz! A mosquito whined in my ear.", o: ["Alliteration", "Hyperbole", "Onomatopoeia"], a: 2, e: "“Bzzz” imitates the sound of the mosquito." },
      { q: "Her angry words were arrows aimed straight at me.", o: ["Metaphor", "Simile", "Onomatopoeia"], a: 0, e: "Her words are called arrows directly, without like or as, so it is a metaphor." },
      { q: "The leaves whispered secrets to one another.", o: ["Hyperbole", "Personification", "Rule of three"], a: 1, e: "Leaves cannot whisper secrets. They are given human actions." },
      { q: "Wasn’t it obvious that the boy was lying?", o: ["Rhetorical question", "Metaphor", "Alliteration"], a: 0, e: "The question is asked to make a point, not to get an answer." }
    ] },
    { type: "rewrite", title: "Add a simile or personification", intro: "Make each plain sentence more vivid. Add a simile <b>or</b> personification as the task says.", items: [
      { q: "Add a simile: The car was fast.", a: "The car shot down the expressway like a bullet." },
      { q: "Add personification: The door opened.", a: "The old door creaked open, groaning as if it had just been woken up." },
      { q: "Add a simile: My hands were cold.", a: "My hands were as cold as ice cubes from the freezer." },
      { q: "Add personification: The wind blew.", a: "The wind tugged at my umbrella and tried to snatch it from my hand." },
      { q: "Add a simile: The baby slept.", a: "The baby slept as peacefully as a kitten curled up in the sun." },
      { q: "Add personification: The alarm clock rang.", a: "My alarm clock screamed at me to get out of bed." },
      { q: "Add a simile: The hall was quiet.", a: "The hall was as quiet as a library at midnight." },
      { q: "Add personification: The flowers moved in the breeze.", a: "The sunflowers nodded and waved at us as we walked past." }
    ] }
  ] },
{ id: "en-suspense", group: "Techniques", order: 42, title: "Suspense and climax",
  intro: "The climax is the most exciting part of your story. Learn how to slow it down and build suspense so your reader cannot stop reading.",
  blocks: [
    { type: "cards", title: "Six suspense tricks", items: [
      { tag: "Trick 1", title: "Slow down time", text: "At the big moment, describe every second. Use more sentences, not fewer.", ex: "The vase wobbled. It tipped to one side. For a moment it hung in the air, and then it began to fall." },
      { tag: "Trick 2", title: "Short sentences", text: "Short, punchy sentences make the reader read faster and feel the tension.", ex: "I stopped. I listened. Silence. Then a footstep." },
      { tag: "Trick 3", title: "Senses at the scary moment", text: "Fear sharpens every sense. What can the character hear, feel, smell?", ex: "My own breathing sounded deafening. The air smelled of damp and rust." },
      { tag: "Trick 4", title: "Cliffhanger paragraph endings", text: "End a paragraph at a tense moment so the reader must read on.", ex: "I reached for the handle. That was when the lights went out." },
      { tag: "Trick 5", title: "Foreshadowing", text: "Drop a small hint early that something will go wrong later.", ex: "Dad had warned me twice that the old ladder was wobbly. I did not listen." },
      { tag: "Trick 6", title: "Ticking clock", text: "Give the character a time limit to make everything more urgent.", ex: "The bus would leave in three minutes, and I still could not find my wallet." }
    ] },
    { type: "text", title: "Worked example", html: "<b>Flat:</b> I heard a noise in the kitchen. I went to look. It was a cat. I was relieved.<br><br><b>Tense:</b> <i>Clink.</i> I sat up in bed. Someone was in the kitchen. I swung my legs off the bed and crept down the dark corridor, my heart thudding so loudly I was sure the burglar could hear it. The kitchen door was open just a crack. A shadow moved across the floor. I held my breath, reached for the light switch and flicked it on.<br><br>Two glowing green eyes stared back at me from the top of the fridge.<br><br>“Meow,” said Mrs Wong’s cat.<br><br>I sank against the wall and let out the breath I had been holding." },
    { type: "tip", html: "<b>Tip:</b> Notice how the tense version uses a sound word, a short sentence, a heartbeat, a shadow and a one-line paragraph before the surprise. Speed up the boring parts and slow down the exciting part." },
    { type: "rewrite", title: "Make the climax tense", intro: "Each climax is flat. Rewrite it using at least two suspense tricks.", items: [
      { q: "My brother fell into the pool. My dad jumped in and saved him.", a: "Splash! My brother had vanished. Only a few bubbles rose where he had been. “Dad!” I screamed. In a flash, Dad dived in, fully dressed. The seconds stretched like hours. Then Dad burst through the surface, my brother coughing and spluttering in his arms." },
      { q: "I lost Mum at the supermarket. Then I found her.", a: "I turned around. Mum was gone. Trolleys rolled past, but none of the faces were hers. My throat tightened. Aisle seven. Aisle eight. Nothing. Then I heard it: “Wei Ming!” I spun around, and there she was, waving a packet of noodles." },
      { q: "The lights went out during the storm. We found a torch.", a: "Crack! Thunder shook the windows, and everything went black. I could not see my own hand. Somewhere, my little sister began to whimper. I felt my way along the cold wall, inch by inch, until my fingers closed around the torch in the drawer." },
      { q: "I almost missed the bus. I caught it.", a: "The bus was already pulling away. I ran, my bag thumping against my back. Twenty metres. Ten. My lungs burned. I banged on the door, and with a hiss, it swung open." },
      { q: "A dog chased me. I climbed onto a bench.", a: "A low growl came from behind the bushes. I froze. A huge black dog stepped out, teeth bared. I ran. Its paws pounded closer and closer. With one wild leap, I scrambled onto the bench, gasping." },
      { q: "I dropped my phone near the drain, but I caught it.", a: "My phone slipped from my fingers. It bounced once on the pavement, then skidded straight towards the drain. I lunged. My fingers closed around it just as it reached the edge. Got it!" },
      { q: "During the race, I tripped but still finished.", a: "The finishing line was ten metres away when my foot caught on something. The ground rushed up at me. Pain shot through my knee. The crowd gasped. Gritting my teeth, I pushed myself up and stumbled forward, one step, two steps, across the line." },
      { q: "I heard footsteps behind me in the dark car park. It was my neighbour.", a: "Tap. Tap. Tap. The footsteps behind me matched my own. I walked faster. So did they. My keys trembled in my hand. Just as I reached the lift, a hand touched my shoulder. I spun around, ready to scream. “You dropped this,” said Uncle Lim from next door, holding out my umbrella." }
    ] }
  ] },
{ id: "en-character", group: "Techniques", order: 43, title: "Thoughts and characters",
  intro: "The best stories let us inside a character’s head, and the character learns or changes by the end. Here is how.",
  blocks: [
    { type: "cards", title: "Four character tools", items: [
      { tag: "Inside the head", title: "Inner thoughts", text: "Show what your character is thinking. You can write it in italics or with “I thought”.", ex: "<i>Just walk away,</i> I told myself. <i>It’s not your problem.</i> But my feet would not move." },
      { tag: "Inside the head", title: "Questions in the head", text: "Worried or unsure characters ask themselves questions. This pulls the reader into the dilemma.", ex: "Should I tell the teacher? Would my friends call me a telltale? What would Mum want me to do?" },
      { tag: "Change", title: "Change by the end", text: "Show your character at the start, then show how they are different at the end. That is the lesson of your story.", ex: "Start: I never shared my crayons with anyone.<br>End: I pushed the box of crayons to the middle of the table. “We can all use them,” I said." },
      { tag: "Choice", title: "A choice to make", text: "Give the main character a hard choice. Their decision shows who they really are.", ex: "I could keep the fifty dollars and buy the game, or I could chase after the old man. I had five seconds to decide." },
      { tag: "Both sides", title: "A tug of war inside", text: "Let the character feel pulled two ways before they decide.", ex: "One part of me wanted to laugh along with the others. Another part remembered how it felt when they laughed at me." },
      { tag: "Real", title: "Flaws make characters real", text: "Nobody is perfect. A character who makes a mistake and fixes it is more interesting.", ex: "I was impatient and often snapped at my little brother. That afternoon at the pool, my temper almost got him hurt." }
    ] },
    { type: "tip", html: "<b>Tip:</b> A strong ending often shows the character doing something they could not or would not do at the beginning. Ask yourself: how is my character different now?" },
    { type: "rewrite", title: "Get inside the character", intro: "Follow each instruction. Write two or three sentences.", items: [
      { q: "Add inner thoughts: I saw my friend copying during the test.", a: "I saw Ryan’s eyes slide towards Mei Ling’s paper. <i>He’s cheating,</i> I thought. <i>Should I say something? He’s my best friend.</i>" },
      { q: "Add questions in the head: I broke Grandma’s favourite cup.", a: "I stared at the pieces in my hands. What would Grandma say? Could I glue it back together before she noticed? Would she ever trust me again?" },
      { q: "Give the character a choice: I found the answer key on the teacher’s desk.", a: "The answer key lay right there, just a glance away. I could peek and finally get full marks. Or I could walk back to my seat and trust my own work." },
      { q: "Show the character has changed: At the start, Jun Hao laughed at the new boy’s accent.", a: "At the end of the term, when the others giggled at Faizal’s accent, Jun Hao stood up. “Leave him alone,” he said. “He’s my friend.”" },
      { q: "Show a tug of war: Your friends want you to skip CCA to go to the arcade.", a: "Part of me longed to follow them to the bright, beeping arcade. But another part pictured Coach waiting, and my teammates one player short." },
      { q: "Show a flaw and a lesson: Aisha always boasted about her drawings.", a: "Aisha used to wave her drawings in everyone’s faces. But after seeing how quiet Priya looked when nobody praised her work, Aisha learnt to clap for others first." }
    ] }
  ] },
{ id: "en-ladders", group: "Practice", order: 50, title: "Word ladders",
  intro: "Words can be mild or strong. Tap the words in order from the weakest to the strongest to climb each ladder.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Imagine a volume knob. Turn it up one click at a time. Which word is the quietest? Which is the loudest?" },
    { type: "order", title: "Climb the ladder", intro: "Tap the words from <b>weakest</b> to <b>strongest</b>.", items: [
      { words: ["content", "happy", "delighted", "ecstatic"], hint: "happiness: a little happy to extremely happy" },
      { words: ["uneasy", "scared", "terrified", "petrified"], hint: "fear: a little scared to frozen with fear" },
      { words: ["calm", "annoyed", "angry", "furious"], hint: "anger: calm to furious" },
      { words: ["down", "sad", "miserable", "devastated"], hint: "sadness" },
      { words: ["calm", "uneasy", "nervous", "panicky"], hint: "nerves: calm to panicky" },
      { words: ["tiny", "small", "big", "enormous"], hint: "size: smallest to biggest" },
      { words: ["freezing", "cold", "cool", "warm", "hot"], hint: "temperature: coldest to hottest" },
      { words: ["crawl", "walk", "jog", "sprint"], hint: "speed: slowest to fastest" },
      { words: ["whisper", "talk", "shout", "scream"], hint: "loudness: quietest to loudest" },
      { words: ["dry", "damp", "wet", "soaked"], hint: "wetness: driest to wettest" },
      { words: ["breeze", "strong wind", "gale", "hurricane"], hint: "wind: calmest to strongest" },
      { words: ["dark", "dim", "bright", "dazzling"], hint: "light: darkest to brightest" },
      { words: ["full", "peckish", "hungry", "starving"], hint: "hunger: full to very hungry" },
      { words: ["wide awake", "a little tired", "tired", "exhausted"], hint: "tiredness: wide awake to exhausted" },
      { words: ["sniffle", "cry", "sob", "wail"], hint: "crying: quietest to loudest" },
      { words: ["smile", "giggle", "laugh", "roar with laughter"], hint: "how amused" },
      { words: ["okay", "good", "great", "outstanding"], hint: "how good" },
      { words: ["not great", "bad", "terrible", "disastrous"], hint: "how bad" },
      { words: ["don’t mind", "dislike", "hate", "loathe"], hint: "how much you dislike something" },
      { words: ["quite like", "like", "love", "adore"], hint: "how much you like something" },
      { words: ["second", "minute", "hour", "day", "week"], hint: "time: shortest to longest" },
      { words: ["pond", "lake", "sea", "ocean"], hint: "water: smallest to biggest" }
    ] }
  ] },
{ id: "en-vocabquiz", group: "Practice", order: 51, title: "Vocabulary quiz",
  intro: "Choose the most precise word to fill each blank. More than one word might fit, but only one is the best.",
  blocks: [
    { type: "mcq", title: "Pick the best word", intro: "Read the whole sentence before you choose.", items: [
      { q: "The old man ____ slowly to the bus stop, leaning on his walking stick.", o: ["sprinted", "hobbled", "marched"], a: 1, e: "“Hobbled” shows he walked with difficulty, which fits the walking stick." },
      { q: "“Shh, the baby’s sleeping,” Mum ____.", o: ["whispered", "bellowed", "announced"], a: 0, e: "You speak softly near a sleeping baby." },
      { q: "After running five laps under the hot sun, I was ____.", o: ["bored", "exhausted", "curious"], a: 1, e: "Running five laps would make you very tired." },
      { q: "The ____ smell of durian filled the whole lift.", o: ["faint", "pungent", "gentle"], a: 1, e: "Durian has a very strong smell, so “pungent” fits best." },
      { q: "Wei Ming ____ at the test paper, unable to believe he had full marks.", o: ["glanced", "stared", "peeked"], a: 1, e: "“Stared” means looked for a long time, showing disbelief." },
      { q: "The ____ thunder made the windows rattle.", o: ["deafening", "soft", "quiet"], a: 0, e: "Thunder loud enough to rattle windows is deafening." },
      { q: "My little brother ____ his ice cream before it could melt.", o: ["nibbled", "studied", "gobbled"], a: 2, e: "To eat it quickly before it melts, he gobbled it." },
      { q: "The ____ alley was dark, empty and silent.", o: ["bustling", "deserted", "crowded"], a: 1, e: "Empty and silent means deserted." },
      { q: "Priya was ____ when her drawing won first prize.", o: ["overjoyed", "content", "annoyed"], a: 0, e: "Winning first prize brings very strong happiness." },
      { q: "The thief ____ the handbag and ran off.", o: ["borrowed", "snatched", "received"], a: 1, e: "“Snatched” means grabbed quickly and roughly." },
      { q: "Jun Hao ____ his lip nervously as he waited for his results.", o: ["bit", "combed", "folded"], a: 0, e: "Biting your lip is a common sign of nervousness." },
      { q: "The ____ puppy shivered under the void deck bench, its fur dripping from the rain.", o: ["proud", "bossy", "frightened"], a: 2, e: "A wet puppy shivering and hiding under a bench is frightened." },
      { q: "Aisha ____ through the crowd to reach her mother.", o: ["squeezed", "floated", "crawled"], a: 0, e: "You squeeze through a tight crowd." },
      { q: "The ____ classroom had no papers on the floor and every desk was neatly arranged.", o: ["cluttered", "spotless", "dusty"], a: 1, e: "No mess at all means spotless." },
      { q: "“I didn’t do it!” Ryan ____, stamping his foot.", o: ["murmured", "protested", "yawned"], a: 1, e: "Stamping his foot shows he is objecting strongly: he protested." },
      { q: "We ____ along the beach, enjoying the cool evening breeze.", o: ["strolled", "dashed", "trudged"], a: 0, e: "“Strolled” is a slow, relaxed walk, which matches enjoying the breeze." },
      { q: "The soldiers ____ in perfect rows during the National Day Parade.", o: ["tiptoed", "wandered", "marched"], a: 2, e: "Soldiers march in step." },
      { q: "Mum was ____ when I came home three hours late without calling.", o: ["frantic", "relaxed", "amused"], a: 0, e: "A parent who has not heard from their child for hours would be frantic with worry." },
      { q: "The ____ girl hid behind her father when the visitors arrived.", o: ["confident", "timid", "rude"], a: 1, e: "Hiding from visitors shows she is timid (shy)." },
      { q: "After the storm, the field was ____ and our shoes sank into the mud.", o: ["dusty", "parched", "waterlogged"], a: 2, e: "Shoes sinking into mud means the field was full of water: waterlogged." },
      { q: "The magician’s trick left the audience ____.", o: ["astonished", "sleepy", "jealous"], a: 0, e: "A great magic trick causes great surprise." },
      { q: "Grandpa ____ the photograph gently, remembering the old days.", o: ["crumpled", "stroked", "tore"], a: 1, e: "“Stroked” is gentle and loving, matching his memories." },
      { q: "The ____ smell of freshly baked bread drifted from the bakery.", o: ["musty", "rotten", "inviting"], a: 2, e: "Fresh bread smells pleasant, so “inviting” fits." },
      { q: "Ahmad ____ the heavy box up the stairs, panting with every step.", o: ["lugged", "tossed", "flicked"], a: 0, e: "“Lugged” means carried something heavy with effort." },
      { q: "When she saw the spider, my sister let out a ____ scream.", o: ["gentle", "piercing", "polite"], a: 1, e: "A sudden scare causes a sharp, loud, piercing scream." }
    ] }
  ] },
{ id: "en-topics", group: "Practice", order: 52, title: "Composition topics",
  intro: "Need an idea? Pick a topic at your level, read the plot ideas, then plan and write your own story.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> The plot ideas are only starting points. Change the characters, the place or the problem to make the story your own." },
    { type: "topics", items: [
      { title: "My New Friend", theme: "Friendship", level: "P1–P2", ideas: ["A shy new classmate sits alone at recess. You share your snack and find out you both love dinosaurs.", "You meet a girl at the playground who teaches you to ride a scooter."] },
      { title: "A Kind Act", theme: "Kindness", level: "P1–P2", ideas: ["An old lady drops her oranges at the market and you help pick them up.", "Your friend forgets her water bottle on a hot day and you share yours."] },
      { title: "The Lost Teddy Bear", theme: "Lost and found", level: "P1–P2", ideas: ["Your little sister leaves her teddy on the MRT train. You go back to the station to ask for help.", "Your teddy goes missing at home, and you find the cat sleeping on it."] },
      { title: "My Birthday Party", theme: "Family", level: "P1–P2", ideas: ["Your family plans a surprise party at the void deck.", "It rains on your party, but you find a fun way to play indoors."] },
      { title: "A Day at the Zoo", theme: "Adventure", level: "P1–P2", ideas: ["A monkey steals your hat and the zookeeper helps get it back.", "You see a baby elephant take its very first bath."] },
      { title: "Helping Mum at Home", theme: "Helping others", level: "P1–P2", ideas: ["Mum is sick, so you help to cook a simple dinner with Dad.", "You try to wash the dishes but make a big, bubbly mess."] },
      { title: "The Broken Toy", theme: "Mistake", level: "P1–P2", ideas: ["You break your brother’s toy car by accident and decide to tell the truth.", "You and a friend argue over a toy and it breaks. You learn to take turns."] },
      { title: "My Pet", theme: "Family", level: "P1–P2", ideas: ["Your hamster escapes from its cage and you search the whole flat.", "Your puppy learns its first trick after many tries."] },
      { title: "A Rainy Day", theme: "Everyday life", level: "P1–P2", ideas: ["You forget your umbrella and a friend shares hers.", "You cannot go out, so your family builds a blanket fort."] },
      { title: "Sports Day", theme: "Competition", level: "P1–P2", ideas: ["You fall in the race but get up and finish.", "Your class wins the relay because everyone works together."] },
      { title: "Sharing Is Caring", theme: "Kindness", level: "P1–P2", ideas: ["You have the only box of colour pencils at your table.", "You share your umbrella with a boy you do not know."] },
      { title: "My Visit to Grandma", theme: "Family", level: "P1–P2", ideas: ["Grandma teaches you how to make ang ku kueh.", "You help Grandma water the plants along her corridor."] },
      { title: "An Act of Kindness", theme: "Kindness", level: "P3–P4", ideas: ["A classmate is laughed at for his old shoes. You stand up for him.", "You help an elderly man who is confused at the bus interchange."] },
      { title: "A Mistake I Made", theme: "Mistake", level: "P3–P4", ideas: ["You copy a friend’s homework and both of you get into trouble.", "You leave the tap running and flood the bathroom."] },
      { title: "Lost in a Crowd", theme: "Lost and found", level: "P3–P4", ideas: ["You get separated from your family at the night market.", "You lose your class during a learning journey at the museum."] },
      { title: "The Accident", theme: "Accident", level: "P3–P4", ideas: ["Your friend falls off his bicycle at the park connector and you get help.", "You knock over a display at the supermarket while playing."] },
      { title: "A Day I Will Never Forget", theme: "Adventure", level: "P3–P4", ideas: ["Your family gets stuck in a lift during a blackout.", "You go kayaking for the first time and capsize."] },
      { title: "The Competition", theme: "Competition", level: "P3–P4", ideas: ["You practise for weeks for a spelling bee, then freeze on stage.", "Your team loses a match, but you learn something important."] },
      { title: "A Good Friend", theme: "Friendship", level: "P3–P4", ideas: ["Your best friend helps you when you are injured at CCA.", "You and your friend quarrel, then make up after a misunderstanding is cleared."] },
      { title: "Being Honest", theme: "Honesty", level: "P3–P4", ideas: ["The cashier gives you too much change.", "You accidentally break a classmate’s ruler and must decide whether to own up."] },
      { title: "A Surprise", theme: "Family", level: "P3–P4", ideas: ["You and your siblings plan a surprise for Mum on Mother’s Day.", "Dad comes home early from an overseas trip without telling anyone."] },
      { title: "Trouble at Recess", theme: "School", level: "P3–P4", ideas: ["Someone’s wallet goes missing and a classmate is wrongly blamed.", "A loud quarrel breaks out in the canteen queue and you have to decide what to do."] },
      { title: "A Brave Act", theme: "Courage", level: "P3–P4", ideas: ["You help a child who is stuck at the top of the playground net.", "You speak up when older children are bullying a younger pupil."] },
      { title: "Helping a Stranger", theme: "Helping others", level: "P3–P4", ideas: ["A tourist cannot find her way and you help her at the MRT station.", "You see a delivery rider fall and you call for help."] },
      { title: "A Lesson Learnt", theme: "Mistake", level: "P5–P6", ideas: ["You ignore safety rules on a camp and someone gets hurt.", "You let a friend take the blame for something you did, then feel guilty."] },
      { title: "A Difficult Decision", theme: "Honesty", level: "P5–P6", ideas: ["You see your best friend cheating in an important test.", "You find the answers to a test and must decide whether to look."] },
      { title: "An Act of Courage", theme: "Courage", level: "P5–P6", ideas: ["You smell smoke in your HDB block and alert your neighbours.", "You overcome your fear of water to save your younger cousin."] },
      { title: "A Misunderstanding", theme: "Friendship", level: "P5–P6", ideas: ["A friend thinks you spread a rumour about her.", "Your parents think you skipped tuition, but you were helping someone."] },
      { title: "The Day Things Went Wrong", theme: "Accident", level: "P5–P6", ideas: ["Everything goes wrong on the morning of the school concert.", "A family holiday starts with lost passports and missed flights."] },
      { title: "Lost and Found", theme: "Lost and found", level: "P5–P6", ideas: ["You find a lost child crying at the shopping centre.", "You lose your bag with your project inside on the day it is due."] },
      { title: "A Change of Heart", theme: "Kindness", level: "P5–P6", ideas: ["You used to tease a classmate until you visit his home and see his struggles.", "A grumpy neighbour turns out to need help, and you learn to understand him."] },
      { title: "Working as a Team", theme: "Competition", level: "P5–P6", ideas: ["Your group almost fails a project because of arguments, then pulls together.", "Your CCA team must win the last match despite an injured captain."] },
      { title: "An Unexpected Adventure", theme: "Adventure", level: "P5–P6", ideas: ["A nature walk at the reservoir takes a wrong turn as darkness falls.", "A school camp turns exciting when a storm hits at night."] },
      { title: "A Family Crisis", theme: "Family", level: "P5–P6", ideas: ["Grandpa falls at home and you must stay calm and call for help.", "Dad loses his job and the family learns to support one another."] },
      { title: "Standing Up for What Is Right", theme: "Courage", level: "P5–P6", ideas: ["Your friends want you to join in a mean online prank.", "You see older boys throwing things from a high floor and report it, even though you are scared they will find out."] },
      { title: "Something I Regret", theme: "Mistake", level: "P5–P6", ideas: ["You say something hurtful to your grandmother before she goes into hospital.", "You break a promise to a friend and lose his trust."] },
      { title: "A Helping Hand", theme: "Helping others", level: "P5–P6", ideas: ["You volunteer at an elderly home and become friends with a lonely resident.", "You organise a class collection for a family whose flat caught fire."] }
    ] }
  ] },
{ id: "en-studio", group: "Practice", order: 53, title: "Writing studio",
  intro: "Your own writing room. Pick a topic, set the timer and write. Then check your work against the rubric.",
  blocks: [
    { type: "tip", html: "<b>How to use the timer:</b> Spend the first few minutes planning (who, where, problem, climax, ending). Write steadily, and keep the last five minutes to read through and fix spelling, punctuation and tenses. If the timer runs out, finish your sentence and write a short ending; an ending always matters." },
    { type: "studio", minWords: 150, rubric: [
      { name: "Content", points: ["My story answers the topic or picture.", "There is a clear problem and a climax.", "I showed feelings instead of only telling them.", "I used at least two senses to describe the setting.", "My ending shows what the character learnt or how things changed."] },
      { name: "Organisation", points: ["My story has a beginning, middle and end.", "Each new idea starts a new paragraph.", "I used connectors to link my ideas.", "The climax is the longest and most detailed part.", "My opening hooks the reader."] },
      { name: "Language", points: ["I used strong verbs instead of “said”, “went” and “got”.", "I replaced “very ___” with one strong word.", "I used at least one simile, metaphor or personification.", "I started my sentences in different ways.", "My dialogue moves the story forward."] },
      { name: "Accuracy", points: ["My spelling is correct.", "I kept to the past tense.", "Every sentence starts with a capital letter and ends with a full stop, question mark or exclamation mark.", "My dialogue punctuation is correct.", "There are no run-on sentences."] }
    ] }
  ] },
{ id: "en-planner", group: "Practice", order: 54, title: "My story planner",
  intro: "Plan before you write! Fill in each box with a few words. A good plan makes writing much easier.",
  blocks: [
    { type: "planner", fields: [
      { id: "title", label: "Title of my story", ph: "e.g. An Act of Honesty" },
      { id: "who", label: "Who is in my story?", ph: "e.g. me, my brother Ryan, an old man" },
      { id: "where", label: "Where and when?", ph: "e.g. a noisy hawker centre, Saturday lunchtime" },
      { id: "opening", label: "My opening (which type?)", ph: "e.g. setting with sounds and smells / dialogue / a question" },
      { id: "problem", label: "What is the problem?", ph: "e.g. I find a wallet full of money" },
      { id: "climax", label: "The most exciting part", ph: "e.g. my brother wants to keep it, and I feel tempted" },
      { id: "solution", label: "How is it solved?", ph: "e.g. I return it to the old man" },
      { id: "feel_start", label: "Feelings at the start", ph: "e.g. relaxed, curious" },
      { id: "feel_middle", label: "Feelings in the middle", ph: "e.g. tempted, guilty, nervous" },
      { id: "feel_end", label: "Feelings at the end", ph: "e.g. proud, relieved" },
      { id: "senses", label: "Senses I will use", ph: "e.g. clattering plates, smell of fried kway teow, sticky table" },
      { id: "lesson", label: "What did I learn?", ph: "e.g. honesty is worth more than money" }
    ], checks: [
      "My opening does not start with “One day”.",
      "I described the setting with at least two senses.",
      "I introduced my main character early.",
      "The problem appears by the second or third paragraph.",
      "I slowed down the climax with details.",
      "I showed at least three feelings through actions or the body.",
      "I used dialogue that moves the story forward.",
      "Each new speaker starts on a new line.",
      "I used at least one simile or other figurative language.",
      "I used connectors other than “then” and “suddenly”.",
      "My main character made a choice or changed.",
      "My ending shows the lesson or how I felt.",
      "I wrote in the past tense throughout.",
      "I checked spelling and punctuation."
    ] }
  ] },
{ id: "en-models", group: "Model essays", order: 60, title: "Model essays",
  intro: "Read these model stories to see the techniques in action. Coloured highlights show you what the writer did well. Read the notes underneath each one.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Do not copy a model essay. Instead, spot one technique you like, such as the opening or the way feelings are shown, and try it in your own story." },
    { type: "essay", title: "An Act of Honesty", level: "P5–P6", paras: [
      "<mark class=\"s\">The hawker centre was buzzing. Plates clattered, uncles shouted out orders and the smoky smell of fried kway teow drifted through the air.</mark> I was slurping my noodles with my little brother, Ryan, when something black under the next table caught my eye.",
      "<mark class=\"f\">Curious,</mark> I bent down and picked it up. It was a leather wallet, <mark class=\"s\">soft and worn at the edges</mark>, and thick with fifty-dollar notes. <mark class=\"fig\">My eyes grew as wide as saucers.</mark> I had never held so much money in my life.",
      "<mark class=\"d\">“We’re rich!” Ryan whispered, his eyes sparkling. “We could buy that new video game!”</mark>",
      "For a moment, I was <mark class=\"f\">tempted</mark>. <mark class=\"sh\">My heart thumped as I imagined walking out of the shop with the game in my hands.</mark> Who would ever know? <mark class=\"c\">Then</mark> I noticed a small photo tucked inside: an old man smiling, with a little girl on his lap. <mark class=\"sh\">A heavy feeling settled in my stomach</mark>, <mark class=\"fig\">as if I had swallowed a stone</mark>.",
      "<mark class=\"d\">“This isn’t ours,” I said firmly. “Someone must be looking for it.”</mark>",
      "<mark class=\"d\">“But nobody saw us,” Ryan protested, tugging at my sleeve. “Finders keepers!”</mark>",
      "I hesitated. <mark class=\"sh\">I glanced at the noisy crowd around us, then back at the smiling faces in the photo.</mark> <mark class=\"fig\">The wallet seemed to grow heavier and heavier in my hand, as if it knew what I was thinking.</mark>",
      "<mark class=\"c\">Just then,</mark> I spotted an elderly man shuffling between the tables. It was the man in the photo! <mark class=\"sh\">His forehead was creased with worry, and his hands trembled as he lifted chairs and peered beneath them.</mark>",
      "<mark class=\"c\">Without wasting another second,</mark> I hurried over. <mark class=\"d\">“Excuse me, Uncle, is this yours?”</mark>",
      "<mark class=\"sh\">His whole face lit up.</mark> <mark class=\"d\">“Thank you, thank you!” he exclaimed, clutching the wallet to his chest. “This is my money for the whole month.”</mark> He tried to press a fifty-dollar note into my hand, but I shook my head politely. Ryan looked at the note, then at the old man, and <mark class=\"sh\">quietly pushed his hands into his pockets</mark>.",
      "<mark class=\"c\">As we walked home under the bright afternoon sky,</mark> <mark class=\"f\">a warm, proud feeling</mark> filled my chest.",
      "Ryan was silent for a while. Then he nudged me and grinned. <mark class=\"d\">“That was better than any video game,” he admitted.</mark>",
      "That day, I learnt that honesty may cost us something we want, but it gives us something money can never buy: <mark class=\"id\">a clear conscience</mark>. <mark class=\"id\">Honesty really is the best policy.</mark>"
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases and proverbs" }
    ], notes: [
      { title: "Opening", text: "Starts with the setting, using sounds and a smell, instead of “One day”. The reader is in the hawker centre at once." },
      { title: "The problem and the choice", text: "Finding the wallet and wanting the money. The writer slows down here and adds a question in the head: “Who would ever know?”" },
      { title: "Feelings shown with the body", text: "Wide eyes, a thumping heart, a heavy stomach. The writer only names the feeling once or twice." },
      { title: "Dialogue", text: "Short and useful. Ryan’s words show temptation; the narrator’s reply shows the decision. Each new speaker starts a new line." },
      { title: "A small detail that matters", text: "The photo of the old man and the girl is what changes the narrator’s mind. Later, it helps the narrator recognise the owner." },
      { title: "Ending", text: "Ryan changes too, and the last paragraph reflects on the lesson and links back to the title with a proverb." }
    ] },
    { type: "essay", title: "The Day I Got Lost", level: "P3–P4", paras: [
      "<mark class=\"s\">Bright lights twinkled everywhere, and the smell of grilled satay and sweet candy floss filled the air.</mark> It was the opening night of the pasar malam near our block, and I was <mark class=\"f\">bursting with excitement</mark>.",
      "<mark class=\"d\">“Stay close to me, Wei Ming,” Mum said, holding my little sister’s hand.</mark> I nodded, but my eyes were already on a stall selling glowing yo-yos.",
      "I squeezed through the crowd to take a closer look. <mark class=\"c\">A few minutes later,</mark> I turned around to show Mum a bright green yo-yo. She was gone.",
      "<mark class=\"sh\">My heart started to pound.</mark> I looked left and right, but all I could see was <mark class=\"fig\">a sea of strangers</mark>. <mark class=\"s\">People bumped into me, a baby wailed and a loud song blared from a speaker.</mark> <mark class=\"sh\">A lump formed in my throat.</mark> Where was Mum? What if I never found her?",
      "<mark class=\"c\">Then</mark> I remembered what my teacher had said: if you are lost, find someone in uniform. <mark class=\"sh\">Wiping my eyes,</mark> I <mark class=\"id\">plucked up my courage</mark> and walked up to a security guard near the drinks stall.",
      "<mark class=\"d\">“Uncle, I can’t find my mum,” I said, my voice shaking.</mark>",
      "<mark class=\"d\">“Don’t worry, we’ll find her,” he said kindly.</mark> He spoke into his walkie-talkie and asked me to describe Mum.",
      "<mark class=\"c\">Before long,</mark> I heard a familiar voice. <mark class=\"d\">“Wei Ming!”</mark> Mum was rushing towards me, <mark class=\"sh\">her face pale and her eyes red</mark>. She <mark class=\"sh\">hugged me so tightly that I could hardly breathe</mark>.",
      "<mark class=\"f\">I was so relieved</mark> <mark class=\"fig\">that my legs turned as wobbly as jelly</mark>. That night, I learnt to stay close to my family in crowded places. I also learnt that staying calm and asking for help is the smartest thing to do when you are lost."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "Opening with the senses", text: "Sight and smell put the reader right at the night market." },
      { title: "Foreshadowing", text: "Mum’s warning, “Stay close to me”, hints that something will go wrong." },
      { title: "The problem", text: "The writer uses a short sentence, “She was gone.”, to make the moment hit hard." },
      { title: "Questions in the head", text: "“Where was Mum? What if I never found her?” lets us hear Wei Ming’s panic." },
      { title: "A sensible solution", text: "Wei Ming solves the problem himself by remembering good advice and plucking up his courage to ask for help, which makes him a strong main character." },
      { title: "Ending", text: "Relief is shown with a simile, then the writer explains two lessons learnt." }
    ] },
    { type: "essay", title: "A Rainy Day", level: "P1–P2", paras: [
      "It was Saturday morning. Aisha and her brother Adam wanted to play football at the playground. <mark class=\"c\">Just then,</mark> <mark class=\"s\">dark clouds covered the sky and thunder rumbled.</mark>",
      "<mark class=\"s\">Pitter-patter, pitter-patter!</mark> Big drops of rain began to fall. <mark class=\"sh\">Adam’s smile disappeared and he sat down with a sigh.</mark> <mark class=\"d\">“Now we can’t play,” he said sadly.</mark>",
      "Aisha looked around the living room. Then she had an idea. <mark class=\"d\">“Let’s play football indoors!”</mark> she said.",
      "<mark class=\"c\">First,</mark> they rolled up some old socks into a soft ball. <mark class=\"c\">Next,</mark> they used two cushions to make a goal. Mum laughed and moved the vase away.",
      "Aisha kicked the sock ball. Adam jumped to stop it, but it flew into the goal! <mark class=\"sh\">They cheered and gave each other a high five.</mark>",
      "<mark class=\"c\">In the end,</mark> the rain stopped and <mark class=\"fig\">the sun peeped out from behind the clouds</mark>. But Aisha and Adam did not even notice. They were <mark class=\"f\">having too much fun</mark> to go outside!"
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }
    ], notes: [
      { title: "Who, when, where", text: "The first two sentences tell us who is in the story, when it happens and what they want to do." },
      { title: "A sound word", text: "“Pitter-patter” lets the reader hear the rain." },
      { title: "Showing feelings", text: "Adam’s smile disappears and he sighs. We can tell he is sad from what he does." },
      { title: "Order words", text: "“First”, “Next” and “In the end” help the reader follow each step." },
      { title: "A happy ending", text: "The problem is solved in a clever way, and the sun peeping out is personification." }
    ] }
  ] }
] });
